// TÖLVA service worker. Generated by scripts/build-sw.mjs from scripts/sw-template.js; do not
// edit sw.js by hand. The site and its data are precached under a version that changes with
// their contents, except the cast's pictures and the other voices' manifests, which join that
// cache when first fetched. Generated audio goes into a separate cache when played (or all at once
// from Settings) and survives updates: each file name is a hash of its text, and its URL carries a
// hash of its bytes (?v=), so a file rendered again is fetched again.

const VERSION = '__VERSION__';
const CORE = `tolva-core-${VERSION}`;
const AUDIO = 'tolva-audio-v1';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CORE).then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' })))));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('tolva-core-') && k !== CORE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// The page asks the waiting worker to take over when the learner accepts an update.
self.addEventListener('message', (event) => {
  if (event.data?.type === 'skipWaiting') self.skipWaiting();
  if (event.data?.type === 'version') event.source?.postMessage({ type: 'version', version: VERSION });
});

// Media elements ask for byte ranges; answer them from the cached file.
async function ranged(request, response) {
  const range = request.headers.get('range');
  if (!range || response.status !== 200) return response;
  const body = await response.arrayBuffer();
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  const start = Number(m?.[1] || 0);
  const end = m?.[2] ? Math.min(Number(m[2]), body.byteLength - 1) : body.byteLength - 1;
  return new Response(body.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': response.headers.get('Content-Type') || 'audio/mpeg',
      'Content-Range': `bytes ${start}-${end}/${body.byteLength}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}

async function audio(request) {
  const cache = await caches.open(AUDIO);
  const url = request.url.split('#')[0];
  let response = await cache.match(url);
  if (!response) {
    response = await fetch(url);
    if (response.ok) await cache.put(url, response.clone());
  }
  return ranged(request, response);
}

// Left out of the precache to keep the first visit small (scripts/build-sw.mjs ON_USE): kept in
// this version's cache once fetched, so what the learner has seen also works offline.
const ON_USE = /\/(assets\/characters\/[^/]+\.svg|data\/audio\/tts-[a-z]+\.json)$/;

async function core(request) {
  const cached = await caches.match(request, { ignoreSearch: request.mode === 'navigate' });
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response.ok && ON_USE.test(new URL(request.url).pathname)) {
      const cache = await caches.open(CORE);
      await cache.put(request, response.clone());
    }
    return response;
  } catch (e) {
    if (request.mode === 'navigate') return (await caches.match('learn.html')) ?? Response.error();
    throw e;
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (/\/data\/audio\/.+\.mp3$/.test(url.pathname)) event.respondWith(audio(request));
  else event.respondWith(core(request));
});
